import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        String text = st.nextToken();
        int k = Integer.parseInt(st.nextToken());
        String[] pats = new String[k];
        int total = 1;
        for (int i = 0; i < k; i++) { pats[i] = st.nextToken(); total += pats[i].length(); }
        int[][] nxt = new int[total][26];
        for (int[] row : nxt) Arrays.fill(row, -1);
        int size = 1;
        int[] ends = new int[k];
        for (int i = 0; i < k; i++) {
            int v = 0;
            for (char ch : pats[i].toCharArray()) {
                int c = ch - 'a';
                if (nxt[v][c] < 0) nxt[v][c] = size++;
                v = nxt[v][c];
            }
            ends[i] = v;
        }
        int[] fail = new int[size], order = new int[size];
        int head = 0, tail = 0;
        for (int c = 0; c < 26; c++) {
            int u = nxt[0][c];
            if (u < 0) nxt[0][c] = 0; else order[tail++] = u;
        }
        while (head < tail) {
            int v = order[head++];
            for (int c = 0; c < 26; c++) {
                int u = nxt[v][c];
                if (u < 0) nxt[v][c] = nxt[fail[v]][c];
                else { fail[u] = nxt[fail[v]][c]; order[tail++] = u; }
            }
        }
        long[] cnt = new long[size];
        int v = 0;
        for (int i = 0; i < text.length(); i++) { v = nxt[v][text.charAt(i) - 'a']; cnt[v]++; }
        for (int i = tail - 1; i >= 0; i--) cnt[fail[order[i]]] += cnt[order[i]];
        StringBuilder out = new StringBuilder();
        for (int e : ends) out.append(cnt[e]).append('\n');
        System.out.print(out);
    }
}

