#include <bits/stdc++.h>
using namespace std;
int main() {
    string text;
    int k;
    cin >> text >> k;
    vector<string> pats(k);
    vector<array<int, 26>> nxt(1);
    nxt[0].fill(-1);
    vector<int> ends(k);
    for (int i = 0; i < k; i++) {
        cin >> pats[i];
        int v = 0;
        for (char ch : pats[i]) {
            int c = ch - 'a';
            if (nxt[v][c] < 0) {
                nxt[v][c] = nxt.size();
                nxt.push_back({});
                nxt.back().fill(-1);
            }
            v = nxt[v][c];
        }
        ends[i] = v;
    }
    int size = nxt.size();
    vector<int> fail(size, 0), order;
    queue<int> q;
    for (int c = 0; c < 26; c++) {
        int u = nxt[0][c];
        if (u < 0) nxt[0][c] = 0; else q.push(u);
    }
    while (!q.empty()) {
        int v = q.front(); q.pop();
        order.push_back(v);
        for (int c = 0; c < 26; c++) {
            int u = nxt[v][c];
            if (u < 0) nxt[v][c] = nxt[fail[v]][c];
            else { fail[u] = nxt[fail[v]][c]; q.push(u); }
        }
    }
    vector<long long> cnt(size, 0);
    int v = 0;
    for (char ch : text) { v = nxt[v][ch - 'a']; cnt[v]++; }
    for (int i = (int)order.size() - 1; i >= 0; i--) cnt[fail[order[i]]] += cnt[order[i]];
    for (int e : ends) printf("%lld\n", cnt[e]);
    return 0;
}
